// `lukeSkywalker: Human`, with an implicit CursorBuilder[Human]
val name: Result[Json] =
  for {
    c <- CursorBuilder[Human].build(Context(StarWarsMapping.HumanType), lukeSkywalker)
    f <- c.field("name", None)
    n <- f.asNullable.flatMap(_.toResultOrError("missing"))
    l <- n.asLeaf
  } yield l

// name == Result.Success(Json.fromString("Luke Skywalker"))

val appearsIn: Result[List[Json]] =
  for {
    c <- CursorBuilder[Character].build(Context(StarWarsMapping.CharacterType), lukeSkywalker)
    f <- c.field("appearsIn", None)
    n <- f.asNullable.flatMap(_.toResultOrError("missing"))
    l <- n.asList(List)
    s <- l.traverse(_.asLeaf)
  } yield s

// s == List(Json.fromString("NEWHOPE"), Json.fromString("EMPIRE"), Json.fromString("JEDI"))

val homePlanet: Result[Json] =
  for {
    c <- CursorBuilder[Character].build(Context(StarWarsMapping.CharacterType), lukeSkywalker)
    h <- c.narrow(StarWarsMapping.HumanType)   // Character -> Human
    m <- h.field("homePlanet", None)
    n <- m.asNullable.flatMap(_.toResultOrError("missing"))
    l <- n.asLeaf
  } yield l

// homePlanet == Result.Success(Json.fromString("Tatooine"))

// StarWarsMapping is a generic Mapping[IO]
val query = """
  query {
    character(id: "1000") { name }
  }
"""

val res: IO[Json] = StarWarsMapping.compileAndRun(query)

// res produces:
// { "data": { "character": { "name": "Luke Skywalker" } } }
